      case (state)
        3'b000: begin // State A
          if (s) state <= 3'b001;
          else begin
            counter <= 3'b000;
            w_history <= 2'b00;
            w_count <= 2'b00;
          end
        end
        3'b001: begin // State B
          counter <= counter + 1;
          w_history <= {w, w_history[1]};
          if (counter == 3) begin
            w_count <= w_count + {w, w_history[1]};
            if (w_count == 2) z <= 1'b1;
            else z <= 1'b0;
            counter <= 3'b000;
            w_history <= 2'b00;
            w_count <= 2'b00;
            state <= 3'b000;
          end
        end
      endcase
    end
  end
endmodule
